enum MDLTRACKTYPE : std::uint32_t { TRACK_NO_INTERP, TRACK_DONT_INTERP=TRACK_NO_INTERP, TRACK_LINEAR, TRACK_HERMITE, TRACK_BEZIER, NUM_TRACK_TYPES };
template<class T>struct MDLKEYFRAME{int time=0;unsigned sequence=0;T value{};T inTan{};T outTan{};};
template<class T>struct MDLKEYTRACK{MDLTRACKTYPE type=TRACK_DONT_INTERP;unsigned globalSequence=~0U;std::vector<MDLKEYFRAME<T>> keys;};
struct MDLGENOBJECT{std::string name;unsigned objectId=0,parentId=~0U,flags=0;MDLKEYTRACK<NTempest::C3Vector>transkeys,scalekeys;MDLKEYTRACK<NTempest::C4Quaternion>rotkeys;};
struct MDLBONE{MDLGENOBJECT object;int geosetId=-1;};struct MDLLIGHTSECTION{MDLGENOBJECT object;unsigned type=0;float attenuationStartValue=0,attenuationEndValue=0,intensityValue=1,ambientIntensityValue=0;C3Color colorValue{1,1,1},ambientColorValue{};MDLKEYTRACK<float>attenuationStart,attenuationEnd,intensity,ambientIntensity,visibility;MDLKEYTRACK<C3Color>color,ambientColor;};
struct MDLPARTICLEEMITTER2ANIM{MDLGENOBJECT object;unsigned squirts=0;MDLKEYTRACK<float>speed,variation,latitude,longitude,gravity,lifeSpan,emissionRate,length,width,zsource,visibility;};
struct MDLRIBBONEMITTERANIM{MDLGENOBJECT object;MDLKEYTRACK<float>heightAbove,heightBelow,alpha,visibility;MDLKEYTRACK<C3Color>color;MDLKEYTRACK<unsigned>slot;};
struct MDLEVENTSECTION{MDLGENOBJECT object;std::vector<int>eventTimes;};struct MDLATTACHMENT{MDLGENOBJECT object;MDLKEYTRACK<float>visibility;unsigned attachmentId=0;std::uint8_t geosetId=0xFF;};
struct MDLDATA{std::vector<CAnimSequence>sequences;std::vector<unsigned>globalSequences;std::vector<MDLBONE>bones,hitTests;std::vector<MDLLIGHTSECTION>lights;std::vector<MDLGENOBJECT>helpers;std::vector<MDLATTACHMENT>attachments;std::vector<MDLPARTICLEEMITTER2ANIM>emitters;std::vector<MDLRIBBONEMITTERANIM>ribbons;std::vector<MDLEVENTSECTION>events;std::vector<NTempest::C3Vector>pivotPoints;std::vector<CAnimMaterialLayer>materials;std::vector<CAnimGeoset>geosets;std::vector<CAnimCameraObj>cameras;std::vector<CAnimTransform>textureAnims;};

template<class Stored,class Value,class Source>void AddKeyFrames(CKeyFrameTrack<Stored,Value>&out,const MDLKEYTRACK<Source>&in,MDLTRACKTYPE forceType=NUM_TRACK_TYPES){out.keys.clear();out.m_keyFrames.clear();out.m_indices.clear();out.SetNumKeys(static_cast<unsigned>(in.keys.size()));out.m_globalSeqId=in.globalSequence;auto type=in.type;if(forceType==TRACK_NO_INTERP)type=TRACK_NO_INTERP;else if(forceType==TRACK_LINEAR&&type>TRACK_LINEAR)type=TRACK_LINEAR;out.m_trackType=static_cast<KEYTYPE>(type);const int adjustment=in.globalSequence!=~0U&&!in.keys.empty()?in.keys.front().time:0;unsigned maxSequence=0;for(const auto&k:in.keys)maxSequence=(std::max)(maxSequence,k.sequence);out.m_indices.resize(in.keys.empty()?0:maxSequence+1);for(unsigned sequence=0;sequence<out.m_indices.size();++sequence){unsigned start=static_cast<unsigned>(out.keys.size());for(const auto&k:in.keys)if(k.sequence==sequence){Stored value{};if constexpr(std::is_same_v<Stored,NTempest::C4QuaternionCompressed>&&std::is_same_v<Source,NTempest::C4Quaternion>)value.Set(k.value);else value=static_cast<Stored>(k.value);out.keys.push_back({k.time-adjustment,value,static_cast<Value>(k.inTan),static_cast<Value>(k.outTan)});out.CKeyFrameTrackBase::AddKey(k.time-adjustment);}out.m_indices[sequence]={start,static_cast<unsigned>(out.keys.size())-start};}}
template<class Stored,class Value,class Source>void AddKeyFramesType(CKeyFrameTrack<Stored,Value>&out,const MDLKEYTRACK<Source>&in,MDLTRACKTYPE forceType){AddKeyFrames(out,in,forceType);}

